FORCEINLINE VectorRegister4Float VectorDot4(VectorRegister4Float Vec1, VectorRegister4Float Vec2)
{
	VectorRegister4Float Temp = VectorMultiply(Vec1, Vec2);
	float32x2_t sum = vpadd_f32(vget_low_f32(Temp), vget_high_f32(Temp));
	sum = vpadd_f32(sum, sum);
	return vdupq_lane_f32(sum, 0);
}

FORCEINLINE VectorRegister4Float VectorReciprocalSqrtEstimate(VectorRegister4Float Vec)
{
	return vrsqrteq_f32(Vec);
}

FORCEINLINE VectorRegister4Double VectorReciprocalSqrtEstimate(VectorRegister4Double Vec)
{
	VectorRegister4Double Result;
	Result.XY = vrsqrteq_f64(Vec.XY);
	Result.ZW = vrsqrteq_f64(Vec.ZW);
	return Result;
}

/**
 * Return the reciprocal of the square root of each component
 *
 * @param Vector	Vector
 * @return			VectorRegister4Float(1/sqrt(Vec.X), 1/sqrt(Vec.Y), 1/sqrt(Vec.Z), 1/sqrt(Vec.W))
 */
FORCEINLINE VectorRegister4Float VectorReciprocalSqrt(VectorRegister4Float Vec)
{
	// Initial estimate
	VectorRegister4Float RecipSqrt = VectorReciprocalSqrtEstimate(Vec);

	// Two refinement
	RecipSqrt = VectorMultiply(vrsqrtsq_f32(Vec, VectorMultiply(RecipSqrt, RecipSqrt)), RecipSqrt);
	return VectorMultiply(vrsqrtsq_f32(Vec, VectorMultiply(RecipSqrt, RecipSqrt)), RecipSqrt);
}

FORCEINLINE VectorRegister4Double VectorReciprocalSqrt(VectorRegister4Double Vec)
{
	// Initial estimate
	VectorRegister4Double RecipSqrt = VectorReciprocalSqrtEstimate(Vec);

// Returns accurate reciprocal square root.
FORCEINLINE VectorRegister4Float VectorReciprocalSqrtAccurate(VectorRegister4Float Vec)
{
	return VectorReciprocalSqrt(Vec);
}

FORCEINLINE VectorRegister4Double VectorReciprocalSqrtAccurate(VectorRegister4Double Vec)
{
	return VectorReciprocalSqrt(Vec);
}

// Uses accurate 1/sqrt, not the estimate
FORCEINLINE VectorRegister4Float VectorNormalizeSafe(VectorRegister4Float Vector, VectorRegister4Float DefaultValue)
{
	const VectorRegister4Float SquareSum = VectorDot4(Vector, Vector);
	const VectorRegister4Float NonZeroMask = VectorCompareGE(SquareSum, GlobalVectorConstants::SmallLengthThreshold);
	const VectorRegister4Float InvLength = VectorReciprocalSqrtAccurate(SquareSum);
	const VectorRegister4Float NormalizedVector = VectorMultiply(InvLength, Vector);
	return VectorSelect(NonZeroMask, NormalizedVector, DefaultValue);
}

void FAnimationRuntime::ConvertPoseToMeshRotation(FCompactPose& LocalPose)
{
	SCOPE_CYCLE_COUNTER(STAT_ConvertPoseToMeshRot);

#if INTEL_ISPC
	if (bAnim_ConvertPoseToMeshRotation_ISPC_Enabled)
	{
		UE_AUTORTFM_OPEN_NO_VALIDATION // Open writes are recorded
		{
			AutoRTFM::RecordOpenWrite(
				LocalPose.GetMutableBones().GetData(),
				LocalPose.GetNumBones() * sizeof(FTransform));
			ispc::ConvertPoseToMeshRotation(
				reinterpret_cast<ispc::FTransform*>(LocalPose.GetMutableBones().GetData()),
				reinterpret_cast<const int32*>(LocalPose.GetBoneContainer().GetCompactPoseParentBoneArray().GetData()),
				LocalPose.GetNumBones());
		};
	}
	else
#endif
	{
		for (FCompactPoseBoneIndex BoneIndex(1); BoneIndex < LocalPose.GetNumBones(); ++BoneIndex)
		{
			const FCompactPoseBoneIndex ParentIndex = LocalPose.GetParentBoneIndex(BoneIndex);

			const FQuat MeshSpaceRotation = LocalPose[ParentIndex].GetRotation() * LocalPose[BoneIndex].GetRotation();
			LocalPose[BoneIndex].SetRotation(MeshSpaceRotation);
		}
	}
}

void FAnimationRuntime::ConvertMeshRotationPoseToLocalSpace(FCompactPose& Pose)
{
	SCOPE_CYCLE_COUNTER(STAT_ConvertMeshRotPoseToLocalSpace);

#if INTEL_ISPC
	if (bAnim_ConvertMeshRotationPoseToLocalSpace_ISPC_Enabled)
	{
		UE_AUTORTFM_OPEN_NO_VALIDATION // Open writes are recorded
		{
			AutoRTFM::RecordOpenWrite(
				Pose.GetMutableBones().GetData(),
				Pose.GetNumBones() * sizeof(FTransform));
			ispc::ConvertMeshRotationPoseToLocalSpace(
				reinterpret_cast<ispc::FTransform*>(Pose.GetMutableBones().GetData()),
				reinterpret_cast<const int32*>(Pose.GetBoneContainer().GetCompactPoseParentBoneArray().GetData()),
				Pose.GetNumBones());
		};
	}
	else
#endif
	{
		for (FCompactPoseBoneIndex BoneIndex(Pose.GetNumBones() - 1); BoneIndex > 0; --BoneIndex)
		{
			const FCompactPoseBoneIndex ParentIndex = Pose.GetParentBoneIndex(BoneIndex);

			FQuat LocalSpaceRotation = Pose[ParentIndex].GetRotation().Inverse() * Pose[BoneIndex].GetRotation();
			Pose[BoneIndex].SetRotation(LocalSpaceRotation);
		}
	}
}

void FAnimationRuntime::AccumulateMeshSpaceRotationAdditiveToLocalPoseInternal(FCompactPose& BasePose, const FCompactPose& MeshSpaceRotationAdditive, float Weight)
{
	SCOPE_CYCLE_COUNTER(STAT_AccumulateMeshSpaceRotAdditiveToLocalPose);

	if (FAnimWeight::IsRelevant(Weight))
	{
		// Convert base pose from local space to mesh space rotation.
		FAnimationRuntime::ConvertPoseToMeshRotation(BasePose);

		// Add MeshSpaceRotAdditive to it
		FAnimationRuntime::AccumulateLocalSpaceAdditivePoseInternal(BasePose, MeshSpaceRotationAdditive, Weight);

		// Convert back to local space
		FAnimationRuntime::ConvertMeshRotationPoseToLocalSpace(BasePose);
	}
}

ENGINE_API void FAnimationRuntime::AccumulateRootSpaceAdditivePoseInternal(FCompactPose& BasePose, const FCompactPose& RootSpaceAdditivePose, float Weight)

	const bool bExpectsAdditivePose=true;
	FPoseContext AdditiveEvalContext(Output, bExpectsAdditivePose);

	Base.Evaluate(Output);
	Additive.Evaluate(AdditiveEvalContext);

	FAnimationPoseData BaseAnimationPoseData(Output);
	const FAnimationPoseData AdditiveAnimationPoseData(AdditiveEvalContext);


	if (bRootSpaceAdditive)
	{
		FAnimationRuntime::AccumulateRootSpaceRotationAdditiveToLocalPose(BaseAnimationPoseData, AdditiveAnimationPoseData, ActualAlpha);
	}
	else
	{
		FAnimationRuntime::AccumulateAdditivePose(BaseAnimationPoseData, AdditiveAnimationPoseData, ActualAlpha, AAT_RotationOffsetMeshSpace);
	}

	Output.Pose.NormalizeRotations();
}
else
{
	Base.Evaluate(Output);
}

/// Panics
///
/// Will panic if `self` is zero length when `glam_assert` is enabled.
#[inline]
#[must_use]
pub fn normalize(self) -> Self {
    Self::from_vec4(Vec4::from(self).normalize())
}

#[must_use]
pub fn length(self) -> f32 {
    math::sqrt(self.dot(self))
}

/// Computes the squared length of `self`.
///
/// This is faster than `length()` as it avoids a square root operation.
#[doc(alias = "magnitude2")]
#[inline]
#[must_use]
pub fn length_squared(self) -> f32 {
    self.dot(self)
}

/// Computes `1.0 / length()`.
///
/// For valid results, `self` must _not_ be of length zero.
#[inline]
#[must_use]
pub fn length_recip(self) -> f32 {
    self.length().recip()
}

/// Will panic if the resulting normalized vector is not finite when `glam_assert` is enabled.
#[inline]
#[must_use]
pub fn normalize(self) -> Self {
    #[allow(clippy::let_and_return)]
    let normalized = self.mul(self.length_recip());
    glam_assert!(normalized.is_finite());
    normalized
}

/// Returns `self` normalized to length 1.0 if possible, else returns `None`.

fn blend_additive_rotation(base: Quat, additive: Quat, alpha: f32) -> Quat {
    let identity_sign = if additive.w >= 0.0 { 1.0 } else { -1.0 };
    let weighted = Quat::from_xyzw(
        additive.x * alpha,
        additive.y * alpha,
        additive.z * alpha,
        identity_sign * (1.0 - alpha) + additive.w * alpha,
    )
    .normalize();
    (weighted * base).normalize()
}

pub fn apply_mesh_space_additive(
    base: &mut Pose,
    additive: &Pose,
    alpha: f32,
    skeleton: &Skeleton,
) {
    if alpha.abs() <= ALPHA_THRESHOLD {
        return;
    }

    materialize_missing_reference_bones(base, skeleton);

    for (bone, additive_index) in &additive.paths {
        let additive_bone = &additive.bones[*additive_index];
        if let Some(base_index) = base.paths.get(bone).copied() {
            merge_non_rotation(&mut base.bones[base_index], additive_bone, alpha);
        } else {
            let mut base_bone = skeleton
                .default_transforms(*bone)
                .map(|transform| BonePose {
                    translation: Some(transform.local.translation),
                    rotation: Some(transform.local.rotation),
                    scale: Some(transform.local.scale),
                    weights: None,
                })
                .unwrap_or_default();
            merge_non_rotation(&mut base_bone, additive_bone, alpha);
            base.add_bone(base_bone, *bone);
        }
    }

    let hierarchy = hierarchy_order(skeleton);
    let mut mesh_rotations: HashMap<bevy_animation_graph::core::pose::BoneId, Quat> =
        HashMap::default();
    for bone in &hierarchy {
        let local = base_local_rotation(base, skeleton, *bone);
        let rotation = skeleton
            .parent(bone)
            .and_then(|parent| mesh_rotations.get(&parent).copied())
            .map(|parent| parent * local)
            .unwrap_or(local);
        mesh_rotations.insert(*bone, rotation);
    }

    for bone in &hierarchy {
        if let (Some(rotation), Some(additive_rotation)) = (
            mesh_rotations.get(bone).copied(),
            additive_rotation(additive, *bone),
        ) {
            mesh_rotations.insert(
                *bone,
                blend_additive_rotation(rotation, additive_rotation, alpha),
            );
        }
    }

    for bone in hierarchy.iter().rev() {
        let Some(rotation) = mesh_rotations.get(bone).copied() else {
            continue;
        };
        let local = skeleton
            .parent(bone)
            .and_then(|parent| mesh_rotations.get(&parent).copied())
            .map(|parent| parent.inverse() * rotation)
            .unwrap_or(rotation)
            .normalize();
        if let Some(base_index) = base.paths.get(bone).copied() {
            base.bones[base_index].rotation = Some(local);
        }
    }

    base.root_motion = merge_root_motion(
        base.root_motion.clone(),
        additive.root_motion.clone(),
        alpha,
    );
}
